package com.ruoyi.ai.mapper;
import org.apache.ibatis.annotations.*; import com.ruoyi.ai.domain.AiUserPreference;
public interface AiUserPreferenceMapper {
 @Select("select user_id as userId,default_model_id as defaultModelId,default_reasoning_effort as defaultReasoningEffort,chat_font_size as chatFontSize,send_shortcut as sendShortcut,double_esc_enabled as doubleEscEnabled,history_entry_visible as historyEntryVisible,auto_restore_last_conversation as autoRestoreLastConversation,assistant_open_mode as assistantOpenMode,create_time as createTime,update_time as updateTime from ai_user_preference where user_id=#{userId}") AiUserPreference selectByUserId(Long userId);
 @Insert("insert into ai_user_preference(user_id,default_model_id,default_reasoning_effort,chat_font_size,send_shortcut,double_esc_enabled,history_entry_visible,auto_restore_last_conversation,assistant_open_mode,create_time,update_time) values(#{userId},#{defaultModelId},#{defaultReasoningEffort},#{chatFontSize},#{sendShortcut},#{doubleEscEnabled},#{historyEntryVisible},#{autoRestoreLastConversation},#{assistantOpenMode},sysdate(),sysdate())") int insert(AiUserPreference p);
 @Update("update ai_user_preference set default_model_id=#{defaultModelId},default_reasoning_effort=#{defaultReasoningEffort},chat_font_size=#{chatFontSize},send_shortcut=#{sendShortcut},double_esc_enabled=#{doubleEscEnabled},history_entry_visible=#{historyEntryVisible},auto_restore_last_conversation=#{autoRestoreLastConversation},assistant_open_mode=#{assistantOpenMode},update_time=sysdate() where user_id=#{userId}") int update(AiUserPreference p);
}